mapper.select:
select `p`.*,d.drug_name, u.real_name from `purchase` p   left join `drug` d on p.drug_id = d.id
   left join `user` u on p.user_id = u.id
   where 1=1

       and `p`.id = #{id}


        and  p.order_number like concat('%',#{orderNumber},'%')


        and  p.title like concat('%',#{title},'%')


        and p.drug_id = #{drugId}


        and p.status = #{status}


        and p.user_id = #{userId}


        and d.drug_name like concat('%',#{drugName},'%')


        and u.real_name like concat('%',#{realName},'%')

    order by `p`.create_time desc
